/* Schematic excavation and the player's persistent evidence board. */
const boardKey='la-tene-board-v7';
let board={hypothesis:'',links:{}};
try{const b=JSON.parse(localStorage.getItem(boardKey));if(b&&typeof b.hypothesis==='string'){board.hypothesis=b.hypothesis;if(b.links&&typeof b.links==='object')for(const [k,v]of Object.entries(b.links))if(/^\d+$/.test(k)&&+k<12&&['supports','challenges','open'].includes(v))board.links[k]=v;}}catch{}
function saveBoard(){try{localStorage.setItem(boardKey,JSON.stringify(board));}catch{storageOK=false;}}
function cellName(n){return 'ABCD'[n%4]+(Math.floor(n/4)+1);}
function artifact(shape){const drawings={sword:'<path d="M45 8 L55 8 L57 69 L50 85 L43 69 Z"/><path d="M32 20 H68 M50 8 V2"/>',tool:'<path d="M44 10 H56 V60 Q82 48 85 72 L72 82 Q63 66 44 78 Z"/>',ring:'<circle cx="50" cy="46" r="30"/><circle cx="50" cy="46" r="18"/>'};return `<svg viewBox="0 0 100 92" aria-hidden="true" class="artifact">${drawings[shape]}</svg>`;}
function renderDig(el,t){
 const f=t.finds.find(x=>x.cell===activeCard),i=t.finds.indexOf(f),phase=selection[i];
 el.innerHTML=`<p>Untersucht das Raster. Drei Fundstellen warten auf euch. <strong>Freilegen → Lage dokumentieren → sichern.</strong></p><p class="small">Schematische Spielgrabung: keine reale Verteilung, Datierung oder gemeinsame Fundschicht. Die Zeichnungen stehen für Fundarten von La Tène.</p><div class="dig-layout"><div><div class="shore-label">THIELLE / ZIHL ≈≈≈</div><div class="dig-grid" aria-label="Grabungsraster mit zwölf Feldern">${Array.from({length:12},(_,n)=>{const item=t.finds.find(x=>x.cell===n),idx=t.finds.indexOf(item),known=selection[idx];return `<button class="dig-cell ${n===activeCard?'selected':''} ${known?'uncovered':''}" data-cell="${n}" aria-label="Feld ${cellName(n)}${known?': '+item.name:''}"><span>${cellName(n)}</span>${known?artifact(item.shape):'<span class="soil">· · ·</span>'}${known==='recorded'?'<b>✓</b>':''}</button>`;}).join('')}</div></div><div class="find-tray" aria-live="polite">${f?`<span class="eyebrow">FUND ${i+1} · ${cellName(f.cell)}</span>${artifact(f.shape)}<h4>${f.name}</h4><p>${f.detail}</p>${phase==='exposed'?`<label for="findCoord">Fundzettel: Tragt das Rasterfeld ein.</label><input id="findCoord" class="entry" maxlength="2" placeholder="z. B. A1" autocomplete="off"><button id="mapFind" class="primary">Lage einzeichnen</button><p id="coordFeedback" role="status"></p>`:phase==='mapped'?'<p>Fundlage dokumentiert. Jetzt könnt ihr den Fund sichern.</p><button id="secureFind" class="primary">In die Fundkiste legen</button>':'<p>✓ Fundlage dokumentiert und Fund gesichert.</p>'}`:activeCard!==null?'<h4>Hier ist kein Fund markiert.</h4><p>Untersucht ein anderes Feld. Auch fundleere Bereiche gehören zur Dokumentation einer Grabung.</p>':'<span class="eyebrow">FUNDKISTE</span><h4>'+ (t.finds.some((_,j)=>selection[j])?'Eure Spuren bleiben im Raster.':'Noch ist alles unter der Oberfläche.')+'</h4><p>Wählt ein Rasterfeld, um es zu untersuchen.</p>'}</div></div><p class="dig-count">${t.finds.filter((_,j)=>selection[j]==='recorded').length} / 3 Funde gesichert</p>`;
 el.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{activeCard=+b.dataset.cell;const idx=t.finds.findIndex(x=>x.cell===activeCard);if(idx>=0&&!selection[idx]){selection[idx]='exposed';changed();}renderInput();});
 if($('#mapFind'))$('#mapFind').onclick=()=>{if(normalize($('#findCoord').value)===normalize(cellName(f.cell))){selection[i]='mapped';changed();renderInput();}else $('#coordFeedback').textContent='Die Koordinate stimmt nicht mit dem freigelegten Feld überein. Prüft Buchstabe und Zahl im Raster.';};
 if($('#secureFind'))$('#secureFind').onclick=()=>{selection[i]='recorded';changed();renderInput();};
}
function caseDone(i){return stations[i].tasks.every((_,j)=>state.results[`${i}-${j}`]?.correct);}
function showReward(){const existing=document.querySelector('.case-reward');if(existing)existing.remove();if(!caseDone(state.station))return;const box=document.createElement('div');box.className='case-reward';box.dataset.contentLanguage='de';box.lang='de';box.innerHTML=`<span class="eyebrow">NEU IN EURER FUNDAKTE</span><h3>${esc(currentStation().reward.title)}</h3><p>${esc(currentStation().reward.text)}</p><button class="primary" id="inspectBoard">Mit unserer Vermutung verbinden →</button>`;$('#input').closest('.card').after(box);$('#inspectBoard').onclick=openBoard;}
function openBoard(){
 const count=stations.filter((_,i)=>caseDone(i)).length;
 $('#boardContent').innerHTML=`<p>Warum liegen die Dinge von La Tène im Wasser? Sammelt Belege für eure Erklärung – und haltet fest, wo sie brüchig wird.</p><label class="entry-label" for="hypothesis">Unsere derzeitige Vermutung</label><textarea id="hypothesis" placeholder="Wir vermuten … Dafür spricht …">${esc(board.hypothesis||state.answers['0-2']?.[0]||'')}</textarea><p class="small">${count} / 12 Aktenstücke verfügbar. Die Zuordnung ist eure Deutung; es gibt dafür keine versteckte Musterlösung.</p><div class="evidence-grid">${stations.map((s,i)=>`<article class="evidence ${caseDone(i)?'available':'sealed'}"><span class="eyebrow">AKTE ${String(i+1).padStart(2,'0')}</span><h3>${esc(caseDone(i)?s.reward.title:s.title)}</h3>${caseDone(i)?`<p>${esc(s.reward.text)}</p><label for="link-${i}">Bezug zu unserer Vermutung</label><select id="link-${i}" data-evidence="${i}"><option value="">Noch nicht verbunden</option><option value="supports" ${board.links[i]==='supports'?'selected':''}>Stützt sie</option><option value="challenges" ${board.links[i]==='challenges'?'selected':''}>Spricht dagegen / begrenzt sie</option><option value="open" ${board.links[i]==='open'?'selected':''}>Öffnet eine neue Frage</option></select>`:`<p>Drei Spuren bearbeiten, um dieses Aktenstück zu sammeln.</p><button class="quiet" data-case="${i}">Akte öffnen →</button>`}</article>`).join('')}</div><div id="boardThreads"></div><div class="actions"><button id="boardFinish" class="primary">Unsere Schlussdeutung schreiben →</button><button id="boardTrip" class="quiet">Mit der Akte nach Neuchâtel →</button></div>`;
 $('#hypothesis').oninput=e=>{board.hypothesis=e.target.value;saveBoard();};
 document.querySelectorAll('[data-evidence]').forEach(e=>e.onchange=()=>{board.links[e.dataset.evidence]=e.value;saveBoard();renderThreads();});
 document.querySelectorAll('[data-case]').forEach(e=>e.onclick=()=>{$('#caseboard').close();start(+e.dataset.case);});
 $('#boardFinish').onclick=()=>{$('#caseboard').close();showResult=true;render();$('#game').scrollIntoView();};
 $('#boardTrip').onclick=()=>{$('#caseboard').close();start(10);};
 $('#closeBoard').onclick=()=>$('#caseboard').close();renderThreads();$('#caseboard').showModal();
}
function renderThreads(){const labels={supports:'Dafür spricht',challenges:'Hier wird es schwierig',open:'Das bleibt offen'};$('#boardThreads').innerHTML=`<div class="thread-summary">${Object.entries(labels).map(([id,label])=>`<section><h3>${label}</h3><p>${stations.filter((_,i)=>caseDone(i)&&board.links[i]===id).map(s=>esc(s.reward.title)).join(' · ')||'Noch kein Aktenstück verbunden.'}</p></section>`).join('')}</div>`;}
function boardReport(){return `\n\nUNSERE VERMUTUNG\n${board.hypothesis||state.answers['0-2']?.[0]||'(offen)'}\n\nVERBUNDENE AKTENSTÜCKE\n`+stations.map((s,i)=>caseDone(i)?`${s.reward.title}: ${s.reward.text}\nBezug: ${{supports:'stützt',challenges:'begrenzt / widerspricht',open:'offene Frage'}[board.links[i]]||'noch nicht verbunden'}`:'').filter(Boolean).join('\n\n');}
